42	} from './template-binding-reorder.ts';
43	import {
44		declareUndeclaredRuntimeDependencies,
45		undeclaredRuntimeDependencies,
46		type InstalledPackage,
47	} from './undeclared-runtime-dependency.ts';
48	import {
49		migrateAngularTsConfig,
50		migrateAngularWorkspace,
51		normalizeFragmentPath,
52		type ConfigChange,
53	} from './angular-workspace-migration.ts';
54	import {
55		isAngularCliOneWorkspace,
56		synthesizeAngularWorkspace,
57		type SynthesizedWorkspace,
58	} from './angular-cli-json-workspace-synthesis.ts';
59	import { tslintConfigRemovals } from './tslint-toolchain-removal.ts';
60	import { declareBuilderPackages } from './builder-package-declaration.ts';
61	import { retargetWorkspaceEngines } from './workspace-engines-retarget.ts';
62	import {
63		addModuleWithProvidersTypeArgument,
64		type ModuleWithProvidersChange,
65	} from './module-with-providers-type-argument.ts';
66	import {
67		parameteriseVoidSubjects,
68		type VoidSubjectChange,
69	} from './subject-void-type-argument.ts';
70	import {
71		parameteriseVoidPromiseExecutors,
72		type VoidExecutorChange,
73	} from './promise-executor-void-parameter.ts';
74	import {
75		parameteriseBaseClasses,
76		type BaseClassParameterisationChange,
77		type GenericBaseClassReading,
78		type UnparameterisedBaseClassDiagnostic,
79	} from './unparameterised-base-class.ts';
80	
81	export type WorkspaceFile = Readonly<{ path: string; source: string }>;
82	
83	export type AngularMigrationInput = Readonly<{
84		packageManifest: WorkspaceFile;
85		workspaceConfig: WorkspaceFile;
86		tsConfig: WorkspaceFile;
87		/** Application source modules, as read from the workspace. */
88		sourceModules: readonly WorkspaceFile[];
89		/**
90		 * Component templates the application owns, kept apart from
91		 * {@link sourceModules} because they are not modules: no source transform
92		 * parses them, and the only capability that reads them reorders directive
93		 * bindings a component class proves are order-dependent. A tree that supplies
94		 * none has none reordered, which is a different thing from having none to
95		 * reorder.
96		 */
97		templates?: readonly WorkspaceFile[];
98		/**
99		 * Webpack fragments a wrapper builder reads, keyed by the path the workspace
100		 * writes for them. A fragment a target references but that is not supplied
101		 * here is reported unread and its wrapper builder is left in place.
102		 */
103		webpackFragments?: readonly WorkspaceFile[];
104		/**
105		 * Every workspace-relative path the tree carries, for capabilities that
106		 * decide a file should no longer exist. Only paths are needed: a file removed
107		 * because the toolchain that read it is gone does not have to be parsed. A
108		 * tree that supplies no list has no files removed.
109		 */
110		workspaceFiles?: readonly string[];
111		/**
112		 * Stylesheets the application owns, kept apart from {@link sourceModules}
113		 * because they are not modules: no source transform parses them, and the only
114		 * capability that reads them resolves package subpaths against an exports map.
115		 */
116		styleSheets?: readonly WorkspaceFile[];
117		/**
118		 * The published surface of packages whose stylesheet subpaths the application
119		 * imports, as read from the installed closure. A package not read here has its
120		 * style imports left exactly as they are.
121		 */
122		packageExports?: readonly PackageExportsReading[];
123		/**
124		 * The installed dependency closure, reduced to declarations and shipped
125		 * imports. Supplying it is what lets undeclared runtime dependencies be
126		 * detected; a tree that supplies none has none detected, which is a different
127		 * thing from having none.
128		 */
129		installedPackages?: readonly InstalledPackage[];
130		/** How the workspace resolves module specifiers written in its own source. */
131		moduleResolution?: ModuleResolution;
132		/**
133		 * `TS2314` as the target line's compiler reported it, per application module.
134		 * A generic base class the application extends bare cannot be parameterised
135		 * from the source alone — the argument is a fact about the installed
136		 * declaration, and which clause is wrong is a fact the compiler states — so
137		 * this capability is reachable only for a caller that has compiled the tree. A
138		 * tree that supplies no diagnostics has no `extends` clause parameterised,
139		 * which is a different thing from having none to parameterise.
140		 */
141		baseClassDiagnostics?: readonly BaseClassDiagnosticReading[];
142		/**
143		 * The generic base classes the application extends, read from the installed
144		 * closure. Supplied beside {@link baseClassDiagnostics}: a diagnostic names the
145		 * clause and this names what the declaration publishes, and the capability
146		 * refuses every site it cannot prove from both.
147		 */
148		genericBaseClasses?: readonly GenericBaseClassReading[];
149	}>;
150	
151	/**
152	 * The `TS2314` diagnostics one application module carries, keyed by the path the
153	 * workspace writes for it. `line` and `column` are the compiler's own 1-based
154	 * pair, and they are positions in the bytes the caller compiled: the capability
155	 * checks that the name it was told to fill is written where it was told, and
156	 * refuses by name rather than editing when it is not.
157	 */
158	export type BaseClassDiagnosticReading = Readonly<{
159		path: string;
160		diagnostics: readonly UnparameterisedBaseClassDiagnostic[];
161	}>;
162	
163	export type MigratedFile = Readonly<{
164		path: string;
165		kind: 'application' | 'workspace';
166		changed: boolean;
167		sha256Before: string;
168		sha256After: string;
169		source: string;
170		changes: readonly string[];
171	}>;
172	
173	export type AngularMigration = Readonly<{
174		cell: string;
175		files: readonly MigratedFile[];
176		applicationFilesChanged: number;
177		workspaceFilesChanged: number;
178		applicationFilesScanned: number;
179		unhandled: readonly string[];
180		/**
181		 * Capabilities the migrated workspace deliberately no longer has, one line
182		 * per removal — a dropped lint target, a dropped configuration file, a
183		 * package the cell read and found no successor for. A reader is owed these by
184		 * name: they are the difference between the era workspace and this one that a
185		 * clean changeset would otherwise hide.
186		 */
187		declaredDifferences: readonly string[];
188		/** Files the migration decided the tree should no longer carry. */
189		removedFiles: readonly string[];
190	}>;
191	
192	function sha256(value: string): string {
193		return createHash('sha256').update(value).digest('hex');
194	}
195	
196	/**
197	 * Parse a workspace document only far enough to decide which format it is in.
198	 *
199	 * A document that is not JSON at all is handed on unparsed: the migration that
200	 * reads it next refuses it with the diagnosable error it already writes, and
201	 * duplicating that refusal here would report the same defect twice under two
202	 * different names.
203	 */
204	function safeParseJson(source: string): unknown {
205		try {
206			return JSON.parse(source) as unknown;
207		} catch {
208			return null;
209		}
210	}
211	
212	function describeConfigChange(change: ConfigChange): string {
213		if (change.to === null) return `removed ${change.path} (was ${change.from ?? 'absent'})`;
214		if (change.from === null) return `added ${change.path} = ${change.to}`;
215		return `${change.path}: ${change.from} -> ${change.to}`;
216	}
217	
218	function describeDependencyChange(change: DependencyChange): string {
219		const target = `${change.field}.${change.name}`;
220		return change.to === null
221			? `removed ${target} (was ${change.from}) — ${change.reason}`
222			: `${target}: ${change.from} -> ${change.to} — ${change.reason}`;
223	}
224	
225	function describeSourceChange(
226		change:
227			| SourceChange
228			| NgrxEffectChange
229			| SentryV8Change
230			| ModalContentParamsChange
231			| StyleImportChange,
232	): string {
233		return `line ${change.line}: ${change.kind} ${change.from} -> ${change.to}`;
234	}
235	
236	/**
237	 * An entry-components removal names no successor, because the property has
238	 * none: what a reader needs from it is which components the dropped list named,
239	 * so the proof that each is still reached can be checked against the literal.
240	 */
241	function describeEntryComponentsChange(change: EntryComponentsChange): string {
242		return `line ${change.line}: ${change.kind} of ${change.symbols.join(', ')}`;
243	}
244	
245	/**
246	 * A type-position insertion names no predecessor, because there was none: what a
247	 * reader needs is the argument that was written and where the capability read it,
248	 * so the claim can be checked against the same two places the source states it.
249	 */
250	function describeModuleWithProvidersChange(change: ModuleWithProvidersChange): string {
251		return `line ${change.line}: ${change.kind} <${change.argument}> read from ${change.readFrom}`;
252	}
253	
254	/**
255	 * `void` is a claim about every value a subject or a promise will ever carry, and
256	 * the evidence for it is the count of zero-argument settlements the capability
257	 * read. The count is reported so the claim can be checked against the binding.
258	 */
259	function describeVoidSubjectChange(change: VoidSubjectChange): string {
260		return (
261			`line ${change.line}: ${change.kind} <void> on ${change.binding}, proved by ` +
262			`${String(change.callSites)} zero-argument next call(s)`
263		);
264	}
265	
266	function describeVoidExecutorChange(change: VoidExecutorChange): string {
267		return (
268			`line ${change.line}: ${change.kind} <void>, proved by ${String(change.callSites)} ` +
269			`zero-argument ${change.parameter} call(s)`
270		);
271	}
272	
273	/**
274	 * A base-class parameterisation carries two facts a reader is owed beyond the
275	 * argument: the package the argument was imported from, and whether importing it
276	 * meant a new declaration in the module.
277	 */
278	function describeBaseClassChange(change: BaseClassParameterisationChange): string {
279		return (
280			`line ${change.line}: ${change.kind} ${change.base}<${change.argument}> from ` +
281			`${change.specifier} (${change.importAdded ? 'import added' : 'existing import extended'})`
282		);
283	}
284	
285	function describeBindingReorderChange(change: BindingReorderChange): string {
286		return (
287			`line ${change.line}: ${change.kind} on <${change.element}> (${change.directive}) — ` +
288			`${change.before.join(', ')} -> ${change.after.join(', ')}, forced by ${change.edges.join('; ')}`
289		);
290	}
291	
292	function file(
293		input: WorkspaceFile,
294		source: string,
295		kind: MigratedFile['kind'],
296		changes: readonly string[],
297	): MigratedFile {
298		return Object.freeze({
299			path: input.path,
300			kind,
301			changed: source !== input.source,
302			sha256Before: sha256(input.source),
303			sha256After: sha256(source),
304			source,
305			changes: Object.freeze([...changes]),
306		});
307	}
308	
309	/**
310	 * Apply every capability of the adapter to one workspace.
311	 *
312	 * Order matters in three places, and each is named where it happens: the
313	 * workspace migration decides which builder targets cannot be carried, and the
314	 * packages those targets released are what the manifest alignment then removes;
315	 * `entryComponents` is dropped after the capabilities that rewrite the literal it
316	 * reads; and the one capability positioned by compiler coordinates runs before
317	 * the capabilities that move them. Nothing else is ordered, and no capability
318	 * reads a file it was not handed.
319	 */
320	export function migrateAngularCliEraWorkspace(
321		input: AngularMigrationInput,
322		cell: AngularTargetCell,
323	): AngularMigration {
324		const unhandled: string[] = [];
325		const declaredDifferences: string[] = [];
326		const fragments: Record<string, string> = {};
327		for (const fragment of input.webpackFragments ?? [])
328			fragments[normalizeFragmentPath(fragment.path)] = fragment.source;
329		/**
330		 * A workspace in the pre-`angular.json` Angular CLI 1.x format is translated
331		 * into the modern one before anything else reads it. Every capability below
332		 * expects a `projects` map with `architect` targets, and the era document has
333		 * neither; synthesizing first is what lets the rest of the adapter run on a
334		 * CLI 1.x tree without one of them learning a second workspace format.
335		 */
336		let synthesis: SynthesizedWorkspace | null = null;
337		let workspaceConfigSource = input.workspaceConfig.source;
338		if (isAngularCliOneWorkspace(safeParseJson(input.workspaceConfig.source))) {
339			synthesis = synthesizeAngularWorkspace(
340				input.workspaceConfig.source,
341				cell,
342				input.workspaceConfig.path,
343			);
344			workspaceConfigSource = synthesis.config;
345			unhandled.push(...synthesis.unhandled);
346			declaredDifferences.push(...synthesis.declaredDifferences);
347		}
348		const workspace = migrateAngularWorkspace(workspaceConfigSource, cell, fragments);
349		unhandled.push(...workspace.unhandled);
350		declaredDifferences.push(...workspace.declaredDifferences);
351		const configRemovals = tslintConfigRemovals(input.workspaceFiles ?? [], cell);
352		declaredDifferences.push(...configRemovals.map((removal) => removal.reason));
353		for (const absorbed of workspace.absorbedFragments)
354			unhandled.push(
355				`${absorbed.path} was absorbed into the official builder and is no longer referenced by any ` +
356					`target; it was left in the tree rather than deleted. Absorbed capabilities: ` +
357					absorbed.capabilities.map((entry) => `${entry.kind} ${entry.detail}`).join(', '),
358			);
359		const manifest: unknown = JSON.parse(input.packageManifest.source);
360		if (typeof manifest !== 'object' || manifest === null || Array.isArray(manifest))
361			throw new Error('Angular migration: the package manifest is not a JSON object');
362		const aligned = alignAngularPackageManifest(
363			manifest as Readonly<Record<string, unknown>>,
364			cell,
365			workspace.removedPackages,
366		);
367		unhandled.push(...aligned.unhandled);
368		declaredDifferences.push(...aligned.declaredDifferences);
369		/**
370		 * Holes the closure carries are closed after the cell alignment, not before:
371		 * the cell decides which lines the workspace runs, and an undeclared edge is
372		 * declared at the line the cell read for it.
373		 */
374		const holes = undeclaredRuntimeDependencies(input.installedPackages ?? []);
375		const declared = declareUndeclaredRuntimeDependencies(aligned.manifest, holes, cell);
376		unhandled.push(...declared.unhandled);
377		declaredDifferences.push(...declared.declaredDifferences);
378		/**
379		 * The packages the migrated workspace's own targets name are declared last,
380		 * after every capability that decides which targets survive: a builder
381		 * declaration for a target the workspace migration removed would install a
382		 * toolchain nothing runs.
383		 */
384		const builders = declareBuilderPackages(declared.manifest, workspace.config, cell);
385		unhandled.push(...builders.unhandled);
386		/**
387		 * The workspace's own runtime declaration is retargeted after every
388		 * capability that decides what the closure is: `engines.node` is a statement
389		 * about the cell the manifest now installs for, so it is written once the
390		 * manifest has finished becoming that cell's manifest. It stands down on a
391		 * workspace that declares no engines, and on one whose declaration already
392		 * admits the cell's Node line.
393		 */
394		const engines = retargetWorkspaceEngines(builders.manifest, cell);
395		unhandled.push(...engines.unhandled);
396		declaredDifferences.push(...engines.declaredDifferences);
397		const tsConfig = migrateAngularTsConfig(input.tsConfig.source, cell);
398		unhandled.push(...tsConfig.unhandled);
399		const files: MigratedFile[] = [
400			file(
401				input.packageManifest,
402				`${JSON.stringify(engines.manifest, null, 2)}\n`,
403				'workspace',
404				[
405					...aligned.changes.map(describeDependencyChange),
406					...declared.declarations.map(
407						(entry) =>
408							`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
409					),
410					...builders.declarations.map(
411						(entry) =>
412							`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
413					),
414					...(engines.retarget === null
415						? []
416						: [
417								`retargeted ${engines.retarget.field} from ${engines.retarget.from} to ` +
418									`${engines.retarget.to} — ${engines.retarget.reason}`,
419							]),
420				],
421			),
422			file(
423				synthesis === null
424					? input.workspaceConfig
425					: { path: synthesis.path, source: input.workspaceConfig.source },
426				workspace.config,
427				'workspace',
428				synthesis === null
429					? workspace.changes.map(describeConfigChange)
430					: [
431							`synthesized ${synthesis.path} from ${synthesis.replacedPath}, the pre-angular.json ` +
432								'Angular CLI 1.x workspace format; the digest recorded before is that file',
433							...synthesis.changes.map(describeConfigChange),
434							...workspace.changes.map(describeConfigChange),
435						],
436			),
437			file(
438				input.tsConfig,
439				tsConfig.config,
440				'workspace',
441				tsConfig.changes.map(describeConfigChange),
442			),
443		];
444		/**
445		 * Source capabilities run in sequence over each module, each one handed what
446		 * the last produced. They are independent — one rewrites module specifiers,
447		 * the next replaces a removed NgRx decorator — and a module is counted as
448		 * changed if any of them changed a byte of it.
449		 */
450		/**
451		 * One capability is not per-module and cannot be: rewriting a modal call site
452		 * without rewriting the content component it supplied is the silent failure
453		 * that capability exists to refuse. It runs over the whole tree first, and
454		 * what it produced is what the per-module capabilities then see.
455		 */
456		const modal = migrateModalContentParams(input.sourceModules, input.moduleResolution ?? {});
457		unhandled.push(...modal.unhandled);
458		const modalByPath = new Map(modal.files.map((entry) => [entry.path, entry]));
459		const baseClassDiagnostics = new Map(
460			(input.baseClassDiagnostics ?? []).map((entry) => [entry.path, entry.diagnostics]),
461		);
462		for (const module of [...input.sourceModules].sort((left, right) =>
463			compareStrings(left.path, right.path),
464		)) {
465			const modalFile = modalByPath.get(module.path);
466			const entrySource = modalFile?.source ?? module.source;
467			/**
468			 * The compiler-positioned capability runs first of the per-module
469			 * capabilities, because its input is a pair of coordinates into bytes the
470			 * caller compiled and every capability that edits the module moves them. It
471			 * is safe wherever it is placed — it refuses a position where the name it was
472			 * told to fill is not written — but placed first it is refused least often
473			 * for a reason that is about ordering rather than about the application.
474			 */
475			const baseClasses = parameteriseBaseClasses(
476				module.path,
477				entrySource,
478				baseClassDiagnostics.get(module.path) ?? [],
479				input.genericBaseClasses ?? [],
480			);
481			const migrated = migrateAngularSourceModule(module.path, baseClasses.source);
482			const effects = migrateNgrxEffectDecorators(module.path, migrated.source);
483			const sentry = migrateSentryV8Tracing(module.path, effects.source);
484			/**
485			 * `entryComponents` is dropped last of the per-module capabilities, and the
486			 * order is not arbitrary: the capability proves, per literal, that every
487			 * component the property names is still reached by `declarations` or
488			 * `bootstrap` of the same literal, and it should see the literal as the
489			 * capabilities before it left it rather than as the era file wrote it.
490			 */
491			const entryComponents = removeEntryComponents(module.path, sentry.source);
492			/**
493			 * Three type-position insertions close the sequence. Each one is a claim
494			 * about a type the source itself already states — the module a static factory
495			 * is declared on, and the `void` a subject or a promise executor proves by
496			 * settling with nothing — so each gates on its own construct and inserts
497			 * nothing where it cannot read one. They are placed after the specifier
498			 * rewrites because the bindings they resolve are the bindings those rewrites
499			 * left, and before nothing: no later capability reads a module.
500			 */
501			const moduleWithProviders = addModuleWithProvidersTypeArgument(
502				module.path,
503				entryComponents.source,
504			);
505			const voidSubjects = parameteriseVoidSubjects(module.path, moduleWithProviders.source);
506			const voidExecutors = parameteriseVoidPromiseExecutors(module.path, voidSubjects.source);
507			unhandled.push(
508				...baseClasses.unhandled,
509				...migrated.unhandled,
510				...effects.unhandled,
511				...sentry.unhandled,
512				...entryComponents.unhandled,
513				...moduleWithProviders.unhandled,
514				...voidSubjects.unhandled,
515				...voidExecutors.unhandled,
516			);
517			files.push(
518				file(module, voidExecutors.source, 'application', [
519					...(modalFile?.changes ?? []).map(describeSourceChange),
520					...baseClasses.changes.map(describeBaseClassChange),
521					...migrated.changes.map(describeSourceChange),
522					...effects.changes.map(describeSourceChange),
523					...sentry.changes.map(describeSourceChange),
524					...entryComponents.changes.map(describeEntryComponentsChange),
525					...moduleWithProviders.changes.map(describeModuleWithProvidersChange),
526					...voidSubjects.changes.map(describeVoidSubjectChange),
527					...voidExecutors.changes.map(describeVoidExecutorChange),
528				]),
529			);
530		}
531		/**
532		 * Templates are the last application capability, and it is cross-file by
533		 * nature: whether a call site's binding order is safe is a question about the
534		 * directive the element resolves to, read from that directive's own class.
535		 * The readings are taken from the modules as the per-module capabilities left
536		 * them, so a directive whose imports those capabilities rewrote still
537		 * resolves. A template no directive reading touches is carried through
538		 * unchanged and still counted, so the scanned total means what it says.
539		 */
540		const directiveReadings: DirectiveBindingReading[] = [];
541		for (const entry of files)
542			if (entry.kind === 'application' && entry.path.endsWith('.ts'))
543				directiveReadings.push(...readDirectiveBindingDependencies(entry.path, entry.source));
544		for (const template of [...(input.templates ?? [])].sort((left, right) =>
545			compareStrings(left.path, right.path),
546		)) {
547			const reordered = reorderTemplateBindings(template.path, template.source, directiveReadings);
548			unhandled.push(...reordered.unhandled);
549			files.push(
550				file(
551					template,
552					reordered.source,
553					'application',
554					reordered.changes.map(describeBindingReorderChange),
555				),
556			);
557		}
558		/**
559		 * Stylesheets are application files too, and a blocked package subpath is an
560		 * application file that no longer builds. Each is offered to every package
561		 * reading the caller supplied; a stylesheet no reading touches is carried
562		 * through unchanged and still counted, so the scanned total means what it says.
563		 */
564		for (const sheet of [...(input.styleSheets ?? [])].sort((left, right) =>
565			compareStrings(left.path, right.path),
566		)) {
567			let source = sheet.source;
568			const changes: string[] = [];
569			for (const reading of input.packageExports ?? []) {
570				const styles = migratePackageStyleImports(sheet.path, source, reading);
571				unhandled.push(...styles.unhandled);
572				declaredDifferences.push(...styles.declaredDifferences);
573				changes.push(...styles.changes.map(describeSourceChange));
574				source = styles.source;
575			}
576			files.push(file(sheet, source, 'application', changes));
577		}
578		const applicationFiles = files.filter((entry) => entry.kind === 'application');
579		return Object.freeze({
580			cell: cell.id,
581			files: Object.freeze(files),
582			applicationFilesChanged: applicationFiles.filter((entry) => entry.changed).length,
583			workspaceFilesChanged: files.filter((entry) => entry.kind === 'workspace' && entry.changed)
584				.length,
585			applicationFilesScanned: applicationFiles.length,
586			unhandled: Object.freeze([...new Set(unhandled)]),
587			declaredDifferences: Object.freeze([...new Set(declaredDifferences)]),
588			removedFiles: Object.freeze([
589				...configRemovals.map((removal) => removal.at),
590				...(synthesis === null ? [] : [synthesis.replacedPath]),
591			]),
592		});
593	}
594

file.content:
/**
 * The composed Angular CLI era migration: workspace configuration, TypeScript
 * configuration, package manifest and application source, lifted onto one
 * declared target cell and reported as a single itemised changeset.
 *
 * The changeset is the product. It records, per file, the bytes before and
 * after as digests and the individual changes that produced them, and it
 * separates application files from workspace files so that a count of changed
 * application files means what it says: source the application owns, changed by
 * a transform, not a version number edited in a manifest.
 */

import { createHash } from 'node:crypto';
import {
	alignAngularPackageManifest,
	compareStrings,
	type AngularTargetCell,
	type DependencyChange,
} from './angular-target-cell.ts';
import { migrateAngularSourceModule, type SourceChange } from './angular-source-migration.ts';
import {
	migrateModalContentParams,
	type ModalContentParamsChange,
	type ModuleResolution,
} from './modal-content-params-migration.ts';
import { migrateNgrxEffectDecorators, type NgrxEffectChange } from './ngrx-effects-migration.ts';
import {
	migratePackageStyleImports,
	type PackageExportsReading,
	type StyleImportChange,
} from './package-exports-style-imports.ts';
import { migrateSentryV8Tracing, type SentryV8Change } from './sentry-v8-migration.ts';
import {
	removeEntryComponents,
	type EntryComponentsChange,
} from './entry-components-removal.ts';
import {
	readDirectiveBindingDependencies,
	reorderTemplateBindings,
	type BindingReorderChange,
	type DirectiveBindingReading,
} from './template-binding-reorder.ts';
import {
	declareUndeclaredRuntimeDependencies,
	undeclaredRuntimeDependencies,
	type InstalledPackage,
} from './undeclared-runtime-dependency.ts';
import {
	migrateAngularTsConfig,
	migrateAngularWorkspace,
	normalizeFragmentPath,
	type ConfigChange,
} from './angular-workspace-migration.ts';
import {
	isAngularCliOneWorkspace,
	synthesizeAngularWorkspace,
	type SynthesizedWorkspace,
} from './angular-cli-json-workspace-synthesis.ts';
import { tslintConfigRemovals } from './tslint-toolchain-removal.ts';
import { declareBuilderPackages } from './builder-package-declaration.ts';
import { retargetWorkspaceEngines } from './workspace-engines-retarget.ts';
import {
	addModuleWithProvidersTypeArgument,
	type ModuleWithProvidersChange,
} from './module-with-providers-type-argument.ts';
import {
	parameteriseVoidSubjects,
	type VoidSubjectChange,
} from './subject-void-type-argument.ts';
import {
	parameteriseVoidPromiseExecutors,
	type VoidExecutorChange,
} from './promise-executor-void-parameter.ts';
import {
	parameteriseBaseClasses,
	type BaseClassParameterisationChange,
	type GenericBaseClassReading,
	type UnparameterisedBaseClassDiagnostic,
} from './unparameterised-base-class.ts';

export type WorkspaceFile = Readonly<{ path: string; source: string }>;

export type AngularMigrationInput = Readonly<{
	packageManifest: WorkspaceFile;
	workspaceConfig: WorkspaceFile;
	tsConfig: WorkspaceFile;
	/** Application source modules, as read from the workspace. */
	sourceModules: readonly WorkspaceFile[];
	/**
	 * Component templates the application owns, kept apart from
	 * {@link sourceModules} because they are not modules: no source transform
	 * parses them, and the only capability that reads them reorders directive
	 * bindings a component class proves are order-dependent. A tree that supplies
	 * none has none reordered, which is a different thing from having none to
	 * reorder.
	 */
	templates?: readonly WorkspaceFile[];
	/**
	 * Webpack fragments a wrapper builder reads, keyed by the path the workspace
	 * writes for them. A fragment a target references but that is not supplied
	 * here is reported unread and its wrapper builder is left in place.
	 */
	webpackFragments?: readonly WorkspaceFile[];
	/**
	 * Every workspace-relative path the tree carries, for capabilities that
	 * decide a file should no longer exist. Only paths are needed: a file removed
	 * because the toolchain that read it is gone does not have to be parsed. A
	 * tree that supplies no list has no files removed.
	 */
	workspaceFiles?: readonly string[];
	/**
	 * Stylesheets the application owns, kept apart from {@link sourceModules}
	 * because they are not modules: no source transform parses them, and the only
	 * capability that reads them resolves package subpaths against an exports map.
	 */
	styleSheets?: readonly WorkspaceFile[];
	/**
	 * The published surface of packages whose stylesheet subpaths the application
	 * imports, as read from the installed closure. A package not read here has its
	 * style imports left exactly as they are.
	 */
	packageExports?: readonly PackageExportsReading[];
	/**
	 * The installed dependency closure, reduced to declarations and shipped
	 * imports. Supplying it is what lets undeclared runtime dependencies be
	 * detected; a tree that supplies none has none detected, which is a different
	 * thing from having none.
	 */
	installedPackages?: readonly InstalledPackage[];
	/** How the workspace resolves module specifiers written in its own source. */
	moduleResolution?: ModuleResolution;
	/**
	 * `TS2314` as the target line's compiler reported it, per application module.
	 * A generic base class the application extends bare cannot be parameterised
	 * from the source alone — the argument is a fact about the installed
	 * declaration, and which clause is wrong is a fact the compiler states — so
	 * this capability is reachable only for a caller that has compiled the tree. A
	 * tree that supplies no diagnostics has no `extends` clause parameterised,
	 * which is a different thing from having none to parameterise.
	 */
	baseClassDiagnostics?: readonly BaseClassDiagnosticReading[];
	/**
	 * The generic base classes the application extends, read from the installed
	 * closure. Supplied beside {@link baseClassDiagnostics}: a diagnostic names the
	 * clause and this names what the declaration publishes, and the capability
	 * refuses every site it cannot prove from both.
	 */
	genericBaseClasses?: readonly GenericBaseClassReading[];
}>;

/**
 * The `TS2314` diagnostics one application module carries, keyed by the path the
 * workspace writes for it. `line` and `column` are the compiler's own 1-based
 * pair, and they are positions in the bytes the caller compiled: the capability
 * checks that the name it was told to fill is written where it was told, and
 * refuses by name rather than editing when it is not.
 */
export type BaseClassDiagnosticReading = Readonly<{
	path: string;
	diagnostics: readonly UnparameterisedBaseClassDiagnostic[];
}>;

export type MigratedFile = Readonly<{
	path: string;
	kind: 'application' | 'workspace';
	changed: boolean;
	sha256Before: string;
	sha256After: string;
	source: string;
	changes: readonly string[];
}>;

export type AngularMigration = Readonly<{
	cell: string;
	files: readonly MigratedFile[];
	applicationFilesChanged: number;
	workspaceFilesChanged: number;
	applicationFilesScanned: number;
	unhandled: readonly string[];
	/**
	 * Capabilities the migrated workspace deliberately no longer has, one line
	 * per removal — a dropped lint target, a dropped configuration file, a
	 * package the cell read and found no successor for. A reader is owed these by
	 * name: they are the difference between the era workspace and this one that a
	 * clean changeset would otherwise hide.
	 */
	declaredDifferences: readonly string[];
	/** Files the migration decided the tree should no longer carry. */
	removedFiles: readonly string[];
}>;

function sha256(value: string): string {
	return createHash('sha256').update(value).digest('hex');
}

/**
 * Parse a workspace document only far enough to decide which format it is in.
 *
 * A document that is not JSON at all is handed on unparsed: the migration that
 * reads it next refuses it with the diagnosable error it already writes, and
 * duplicating that refusal here would report the same defect twice under two
 * different names.
 */
function safeParseJson(source: string): unknown {
	try {
		return JSON.parse(source) as unknown;
	} catch {
		return null;
	}
}

function describeConfigChange(change: ConfigChange): string {
	if (change.to === null) return `removed ${change.path} (was ${change.from ?? 'absent'})`;
	if (change.from === null) return `added ${change.path} = ${change.to}`;
	return `${change.path}: ${change.from} -> ${change.to}`;
}

function describeDependencyChange(change: DependencyChange): string {
	const target = `${change.field}.${change.name}`;
	return change.to === null
		? `removed ${target} (was ${change.from}) — ${change.reason}`
		: `${target}: ${change.from} -> ${change.to} — ${change.reason}`;
}

function describeSourceChange(
	change:
		| SourceChange
		| NgrxEffectChange
		| SentryV8Change
		| ModalContentParamsChange
		| StyleImportChange,
): string {
	return `line ${change.line}: ${change.kind} ${change.from} -> ${change.to}`;
}

/**
 * An entry-components removal names no successor, because the property has
 * none: what a reader needs from it is which components the dropped list named,
 * so the proof that each is still reached can be checked against the literal.
 */
function describeEntryComponentsChange(change: EntryComponentsChange): string {
	return `line ${change.line}: ${change.kind} of ${change.symbols.join(', ')}`;
}

/**
 * A type-position insertion names no predecessor, because there was none: what a
 * reader needs is the argument that was written and where the capability read it,
 * so the claim can be checked against the same two places the source states it.
 */
function describeModuleWithProvidersChange(change: ModuleWithProvidersChange): string {
	return `line ${change.line}: ${change.kind} <${change.argument}> read from ${change.readFrom}`;
}

/**
 * `void` is a claim about every value a subject or a promise will ever carry, and
 * the evidence for it is the count of zero-argument settlements the capability
 * read. The count is reported so the claim can be checked against the binding.
 */
function describeVoidSubjectChange(change: VoidSubjectChange): string {
	return (
		`line ${change.line}: ${change.kind} <void> on ${change.binding}, proved by ` +
		`${String(change.callSites)} zero-argument next call(s)`
	);
}

function describeVoidExecutorChange(change: VoidExecutorChange): string {
	return (
		`line ${change.line}: ${change.kind} <void>, proved by ${String(change.callSites)} ` +
		`zero-argument ${change.parameter} call(s)`
	);
}

/**
 * A base-class parameterisation carries two facts a reader is owed beyond the
 * argument: the package the argument was imported from, and whether importing it
 * meant a new declaration in the module.
 */
function describeBaseClassChange(change: BaseClassParameterisationChange): string {
	return (
		`line ${change.line}: ${change.kind} ${change.base}<${change.argument}> from ` +
		`${change.specifier} (${change.importAdded ? 'import added' : 'existing import extended'})`
	);
}

function describeBindingReorderChange(change: BindingReorderChange): string {
	return (
		`line ${change.line}: ${change.kind} on <${change.element}> (${change.directive}) — ` +
		`${change.before.join(', ')} -> ${change.after.join(', ')}, forced by ${change.edges.join('; ')}`
	);
}

function file(
	input: WorkspaceFile,
	source: string,
	kind: MigratedFile['kind'],
	changes: readonly string[],
): MigratedFile {
	return Object.freeze({
		path: input.path,
		kind,
		changed: source !== input.source,
		sha256Before: sha256(input.source),
		sha256After: sha256(source),
		source,
		changes: Object.freeze([...changes]),
	});
}

/**
 * Apply every capability of the adapter to one workspace.
 *
 * Order matters in three places, and each is named where it happens: the
 * workspace migration decides which builder targets cannot be carried, and the
 * packages those targets released are what the manifest alignment then removes;
 * `entryComponents` is dropped after the capabilities that rewrite the literal it
 * reads; and the one capability positioned by compiler coordinates runs before
 * the capabilities that move them. Nothing else is ordered, and no capability
 * reads a file it was not handed.
 */
export function migrateAngularCliEraWorkspace(
	input: AngularMigrationInput,
	cell: AngularTargetCell,
): AngularMigration {
	const unhandled: string[] = [];
	const declaredDifferences: string[] = [];
	const fragments: Record<string, string> = {};
	for (const fragment of input.webpackFragments ?? [])
		fragments[normalizeFragmentPath(fragment.path)] = fragment.source;
	/**
	 * A workspace in the pre-`angular.json` Angular CLI 1.x format is translated
	 * into the modern one before anything else reads it. Every capability below
	 * expects a `projects` map with `architect` targets, and the era document has
	 * neither; synthesizing first is what lets the rest of the adapter run on a
	 * CLI 1.x tree without one of them learning a second workspace format.
	 */
	let synthesis: SynthesizedWorkspace | null = null;
	let workspaceConfigSource = input.workspaceConfig.source;
	if (isAngularCliOneWorkspace(safeParseJson(input.workspaceConfig.source))) {
		synthesis = synthesizeAngularWorkspace(
			input.workspaceConfig.source,
			cell,
			input.workspaceConfig.path,
		);
		workspaceConfigSource = synthesis.config;
		unhandled.push(...synthesis.unhandled);
		declaredDifferences.push(...synthesis.declaredDifferences);
	}
	const workspace = migrateAngularWorkspace(workspaceConfigSource, cell, fragments);
	unhandled.push(...workspace.unhandled);
	declaredDifferences.push(...workspace.declaredDifferences);
	const configRemovals = tslintConfigRemovals(input.workspaceFiles ?? [], cell);
	declaredDifferences.push(...configRemovals.map((removal) => removal.reason));
	for (const absorbed of workspace.absorbedFragments)
		unhandled.push(
			`${absorbed.path} was absorbed into the official builder and is no longer referenced by any ` +
				`target; it was left in the tree rather than deleted. Absorbed capabilities: ` +
				absorbed.capabilities.map((entry) => `${entry.kind} ${entry.detail}`).join(', '),
		);
	const manifest: unknown = JSON.parse(input.packageManifest.source);
	if (typeof manifest !== 'object' || manifest === null || Array.isArray(manifest))
		throw new Error('Angular migration: the package manifest is not a JSON object');
	const aligned = alignAngularPackageManifest(
		manifest as Readonly<Record<string, unknown>>,
		cell,
		workspace.removedPackages,
	);
	unhandled.push(...aligned.unhandled);
	declaredDifferences.push(...aligned.declaredDifferences);
	/**
	 * Holes the closure carries are closed after the cell alignment, not before:
	 * the cell decides which lines the workspace runs, and an undeclared edge is
	 * declared at the line the cell read for it.
	 */
	const holes = undeclaredRuntimeDependencies(input.installedPackages ?? []);
	const declared = declareUndeclaredRuntimeDependencies(aligned.manifest, holes, cell);
	unhandled.push(...declared.unhandled);
	declaredDifferences.push(...declared.declaredDifferences);
	/**
	 * The packages the migrated workspace's own targets name are declared last,
	 * after every capability that decides which targets survive: a builder
	 * declaration for a target the workspace migration removed would install a
	 * toolchain nothing runs.
	 */
	const builders = declareBuilderPackages(declared.manifest, workspace.config, cell);
	unhandled.push(...builders.unhandled);
	/**
	 * The workspace's own runtime declaration is retargeted after every
	 * capability that decides what the closure is: `engines.node` is a statement
	 * about the cell the manifest now installs for, so it is written once the
	 * manifest has finished becoming that cell's manifest. It stands down on a
	 * workspace that declares no engines, and on one whose declaration already
	 * admits the cell's Node line.
	 */
	const engines = retargetWorkspaceEngines(builders.manifest, cell);
	unhandled.push(...engines.unhandled);
	declaredDifferences.push(...engines.declaredDifferences);
	const tsConfig = migrateAngularTsConfig(input.tsConfig.source, cell);
	unhandled.push(...tsConfig.unhandled);
	const files: MigratedFile[] = [
		file(
			input.packageManifest,
			`${JSON.stringify(engines.manifest, null, 2)}\n`,
			'workspace',
			[
				...aligned.changes.map(describeDependencyChange),
				...declared.declarations.map(
					(entry) =>
						`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
				),
				...builders.declarations.map(
					(entry) =>
						`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
				),
				...(engines.retarget === null
					? []
					: [
							`retargeted ${engines.retarget.field} from ${engines.retarget.from} to ` +
								`${engines.retarget.to} — ${engines.retarget.reason}`,
						]),
			],
		),
		file(
			synthesis === null
				? input.workspaceConfig
				: { path: synthesis.path, source: input.workspaceConfig.source },
			workspace.config,
			'workspace',
			synthesis === null
				? workspace.changes.map(describeConfigChange)
				: [
						`synthesized ${synthesis.path} from ${synthesis.replacedPath}, the pre-angular.json ` +
							'Angular CLI 1.x workspace format; the digest recorded before is that file',
						...synthesis.changes.map(describeConfigChange),
						...workspace.changes.map(describeConfigChange),
					],
		),
		file(
			input.tsConfig,
			tsConfig.config,
			'workspace',
			tsConfig.changes.map(describeConfigChange),
		),
	];
	/**
	 * Source capabilities run in sequence over each module, each one handed what
	 * the last produced. They are independent — one rewrites module specifiers,
	 * the next replaces a removed NgRx decorator — and a module is counted as
	 * changed if any of them changed a byte of it.
	 */
	/**
	 * One capability is not per-module and cannot be: rewriting a modal call site
	 * without rewriting the content component it supplied is the silent failure
	 * that capability exists to refuse. It runs over the whole tree first, and
	 * what it produced is what the per-module capabilities then see.
	 */
	const modal = migrateModalContentParams(input.sourceModules, input.moduleResolution ?? {});
	unhandled.push(...modal.unhandled);
	const modalByPath = new Map(modal.files.map((entry) => [entry.path, entry]));
	const baseClassDiagnostics = new Map(
		(input.baseClassDiagnostics ?? []).map((entry) => [entry.path, entry.diagnostics]),
	);
	for (const module of [...input.sourceModules].sort((left, right) =>
		compareStrings(left.path, right.path),
	)) {
		const modalFile = modalByPath.get(module.path);
		const entrySource = modalFile?.source ?? module.source;
		/**
		 * The compiler-positioned capability runs first of the per-module
		 * capabilities, because its input is a pair of coordinates into bytes the
		 * caller compiled and every capability that edits the module moves them. It
		 * is safe wherever it is placed — it refuses a position where the name it was
		 * told to fill is not written — but placed first it is refused least often
		 * for a reason that is about ordering rather than about the application.
		 */
		const baseClasses = parameteriseBaseClasses(
			module.path,
			entrySource,
			baseClassDiagnostics.get(module.path) ?? [],
			input.genericBaseClasses ?? [],
		);
		const migrated = migrateAngularSourceModule(module.path, baseClasses.source);
		const effects = migrateNgrxEffectDecorators(module.path, migrated.source);
		const sentry = migrateSentryV8Tracing(module.path, effects.source);
		/**
		 * `entryComponents` is dropped last of the per-module capabilities, and the
		 * order is not arbitrary: the capability proves, per literal, that every
		 * component the property names is still reached by `declarations` or
		 * `bootstrap` of the same literal, and it should see the literal as the
		 * capabilities before it left it rather than as the era file wrote it.
		 */
		const entryComponents = removeEntryComponents(module.path, sentry.source);
		/**
		 * Three type-position insertions close the sequence. Each one is a claim
		 * about a type the source itself already states — the module a static factory
		 * is declared on, and the `void` a subject or a promise executor proves by
		 * settling with nothing — so each gates on its own construct and inserts
		 * nothing where it cannot read one. They are placed after the specifier
		 * rewrites because the bindings they resolve are the bindings those rewrites
		 * left, and before nothing: no later capability reads a module.
		 */
		const moduleWithProviders = addModuleWithProvidersTypeArgument(
			module.path,
			entryComponents.source,
		);
		const voidSubjects = parameteriseVoidSubjects(module.path, moduleWithProviders.source);
		const voidExecutors = parameteriseVoidPromiseExecutors(module.path, voidSubjects.source);
		unhandled.push(
			...baseClasses.unhandled,
			...migrated.unhandled,
			...effects.unhandled,
			...sentry.unhandled,
			...entryComponents.unhandled,
			...moduleWithProviders.unhandled,
			...voidSubjects.unhandled,
			...voidExecutors.unhandled,
		);
		files.push(
			file(module, voidExecutors.source, 'application', [
				...(modalFile?.changes ?? []).map(describeSourceChange),
				...baseClasses.changes.map(describeBaseClassChange),
				...migrated.changes.map(describeSourceChange),
				...effects.changes.map(describeSourceChange),
				...sentry.changes.map(describeSourceChange),
				...entryComponents.changes.map(describeEntryComponentsChange),
				...moduleWithProviders.changes.map(describeModuleWithProvidersChange),
				...voidSubjects.changes.map(describeVoidSubjectChange),
				...voidExecutors.changes.map(describeVoidExecutorChange),
			]),
		);
	}
	/**
	 * Templates are the last application capability, and it is cross-file by
	 * nature: whether a call site's binding order is safe is a question about the
	 * directive the element resolves to, read from that directive's own class.
	 * The readings are taken from the modules as the per-module capabilities left
	 * them, so a directive whose imports those capabilities rewrote still
	 * resolves. A template no directive reading touches is carried through
	 * unchanged and still counted, so the scanned total means what it says.
	 */
	const directiveReadings: DirectiveBindingReading[] = [];
	for (const entry of files)
		if (entry.kind === 'application' && entry.path.endsWith('.ts'))
			directiveReadings.push(...readDirectiveBindingDependencies(entry.path, entry.source));
	for (const template of [...(input.templates ?? [])].sort((left, right) =>
		compareStrings(left.path, right.path),
	)) {
		const reordered = reorderTemplateBindings(template.path, template.source, directiveReadings);
		unhandled.push(...reordered.unhandled);
		files.push(
			file(
				template,
				reordered.source,
				'application',
				reordered.changes.map(describeBindingReorderChange),
			),
		);
	}
	/**
	 * Stylesheets are application files too, and a blocked package subpath is an
	 * application file that no longer builds. Each is offered to every package
	 * reading the caller supplied; a stylesheet no reading touches is carried
	 * through unchanged and still counted, so the scanned total means what it says.
	 */
	for (const sheet of [...(input.styleSheets ?? [])].sort((left, right) =>
		compareStrings(left.path, right.path),
	)) {
		let source = sheet.source;
		const changes: string[] = [];
		for (const reading of input.packageExports ?? []) {
			const styles = migratePackageStyleImports(sheet.path, source, reading);
			unhandled.push(...styles.unhandled);
			declaredDifferences.push(...styles.declaredDifferences);
			changes.push(...styles.changes.map(describeSourceChange));
			source = styles.source;
		}
		files.push(file(sheet, source, 'application', changes));
	}
	const applicationFiles = files.filter((entry) => entry.kind === 'application');
	return Object.freeze({
		cell: cell.id,
		files: Object.freeze(files),
		applicationFilesChanged: applicationFiles.filter((entry) => entry.changed).length,
		workspaceFilesChanged: files.filter((entry) => entry.kind === 'workspace' && entry.changed)
			.length,
		applicationFilesScanned: applicationFiles.length,
		unhandled: Object.freeze([...new Set(unhandled)]),
		declaredDifferences: Object.freeze([...new Set(declaredDifferences)]),
		removedFiles: Object.freeze([
			...configRemovals.map((removal) => removal.at),
			...(synthesis === null ? [] : [synthesis.replacedPath]),
		]),
	});
}

