1	/**
2	 * Undeclared runtime dependencies — peer holes — read out of an installed
3	 * dependency closure and closed in the application's own manifest.
4	 *
5	 * A published package states its runtime edges in `dependencies` and
6	 * `peerDependencies`. When the bundles it actually ships import a package it
7	 * declares in neither, the edge exists but nothing in the closure is obliged to
8	 * satisfy it. An installation that works anyway works by accident: some other
9	 * package happened to hoist the module to a place the resolver found. Nothing
10	 * records that, so nothing preserves it, and the first unrelated dependency
11	 * change breaks a build for a reason the manifest cannot explain.
12	 *
13	 * The detection is entirely a reading of the closure's own facts:
14	 *
15	 * - what each installed package's manifest declares, and
16	 * - what each installed package's shipped bundles import.
17	 *
18	 * Nothing here knows which packages have holes. The pair (importer, imported)
19	 * is discovered, never listed. What the capability will not invent is the
20	 * *version*: the range comes from the target cell's community-layer reading,
21	 * chosen by the same mechanical rule every other entry in that table was chosen
22	 * by, and a hole the cell has read no line for is reported rather than guessed
23	 * at. Declaring a dependency at a version nobody read would replace an accident
24	 * with a fabrication.
25	 *
26	 * What closing a hole establishes is narrow, and the reason recorded with the
27	 * change says so: the application now declares an edge the closure previously
28	 * supplied by accident. It does not establish that the declared line's export
29	 * surface matches what the importer's bundles reach for — a build, and then a
30	 * witness, arbitrate that.
31	 */
32	
33	import { builtinModules } from 'node:module';
34	import {
35		compareStrings,
36		ecosystemDispositionOf,
37		type AngularTargetCell,
38		type PackageManifest,
39	} from './angular-target-cell.ts';
40	import { parseModule, type AstNode } from './semantic-module.ts';
41	
42	/** The manifest fields that declare an edge a runtime import may rely on. */
43	export const RUNTIME_DEPENDENCY_FIELDS: readonly string[] = Object.freeze([
44		'dependencies',
45		'peerDependencies',
46		'optionalDependencies',
47	]);
48	
49	/** The manifest fields an application may already close a hole in. */
50	const APPLICATION_DEPENDENCY_FIELDS: readonly string[] = Object.freeze([
51		'dependencies',
52		'devDependencies',
53	]);
54	
55	const NODE_BUILTINS: ReadonlySet<string> = new Set(builtinModules);
56	
57	/** One file of a published package, as installed. */
58	export type InstalledFile = Readonly<{ path: string; source: string }>;
59	
60	/** One bare specifier a package's shipped bundles import, and where from. */
61	export type PackageImport = Readonly<{ specifier: string; from: string }>;
62	
63	/** One installed package, reduced to the two facts the detection needs. */
64	export type InstalledPackage = Readonly<{
65		name: string;
66		version: string;
67		/** Package names declared in any of {@link RUNTIME_DEPENDENCY_FIELDS}. */
68		declared: readonly string[];
69		/** Bare specifiers the shipped bundles import, with the file each came from. */
70		imports: readonly PackageImport[];
71	}>;
72	
73	export type UndeclaredRuntimeDependency = Readonly<{
74		/** The package whose bundles import without declaring. */
75		importer: string;
76		importerVersion: string;
77		/** The package name the bundles reach for. */
78		dependency: string;
79		/** The specifiers, deduplicated and sorted, that produced the hole. */
80		specifiers: readonly string[];
81		/** The shipped files, deduplicated and sorted, the specifiers were read in. */
82		files: readonly string[];
83		/**
84		 * Whether some package in the closure happens to carry the name anyway. A
85		 * hole is a hole either way — the point is that nothing declared the edge —
86		 * but a hole that is currently unsatisfied is also a build that cannot run.
87		 */
88		satisfiedByClosure: boolean;
89	}>;
90	
91	/**
92	 * The package a bare module specifier names, or null when the specifier does
93	 * not name one: a relative or absolute path, a protocol-qualified specifier, or
94	 * a Node builtin, none of which a manifest is expected to declare.
95	 */
96	export function packageNameOfSpecifier(specifier: string): string | null {
97		if (specifier === '' || specifier.startsWith('.') || specifier.startsWith('/')) return null;
98		if (specifier.includes(':')) return null;
99		if (specifier.startsWith('#')) return null;
100		const segments = specifier.split('/').filter((segment) => segment !== '');
101		const first = segments[0];
102		if (first === undefined) return null;
103		if (!first.startsWith('@')) return NODE_BUILTINS.has(first) ? null : first;
104		const second = segments[1];
105		return second === undefined ? null : `${first}/${second}`;
106	}
107	
108	function declaredNames(manifest: Readonly<Record<string, unknown>>): readonly string[] {
109		const names = new Set<string>();
110		for (const field of RUNTIME_DEPENDENCY_FIELDS) {
111			const value = manifest[field];
112			if (typeof value !== 'object' || value === null || Array.isArray(value)) continue;
113			for (const name of Object.keys(value as Record<string, unknown>)) names.add(name);
114		}
115		return Object.freeze([...names].sort(compareStrings));
116	}
117	
118	/** The module specifier of a re-export declaration, when it has one. */
119	function reexportSpecifier(node: AstNode): string | null {
120		if (node.type !== 'ExportAllDeclaration' && node.type !== 'ExportNamedDeclaration') return null;
121		const source = node.source;
122		if (source === null || source === undefined || source.type !== 'Literal') return null;
123		return typeof source.value === 'string' ? source.value : null;
124	}
125	
126	/**
127	 * Read one installed package into the facts the detection needs.
128	 *
129	 * The bundles are parsed, not scanned for text: a specifier is a specifier
130	 * because the module graph says so, not because the bytes of a comment or a
131	 * string constant happened to spell one. Static imports, re-exports and
132	 * dynamic imports with a literal specifier all count, because all three are
133	 * runtime edges the package's own code makes.
134	 */
135	export function readInstalledPackage(
136		manifestSource: string,
137		bundles: readonly InstalledFile[],
138	): InstalledPackage {
139		const parsed: unknown = JSON.parse(manifestSource);
140		if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed))
141			throw new Error('Undeclared runtime dependency reading: a package manifest is not an object');
142		const manifest = parsed as Readonly<Record<string, unknown>>;
143		const name = manifest['name'];
144		const version = manifest['version'];
145		if (typeof name !== 'string')
146			throw new Error('Undeclared runtime dependency reading: a package manifest declares no name');
147		const imports: PackageImport[] = [];
148		for (const bundle of bundles) {
149			const module = parseModule('Undeclared runtime dependency reading', bundle.path, bundle.source);
150			for (const record of module.imports)
151				imports.push(Object.freeze({ specifier: record.specifier, from: bundle.path }));
152			for (const statement of module.ast.body as readonly AstNode[]) {
153				const specifier = reexportSpecifier(statement);
154				if (specifier !== null) imports.push(Object.freeze({ specifier, from: bundle.path }));
155			}
156		}
157		return Object.freeze({
158			name,
159			version: typeof version === 'string' ? version : '',
160			declared: declaredNames(manifest),
161			imports: Object.freeze(imports),
162		});
163	}
164	
165	/**
166	 * Every runtime edge the closure's own packages make without declaring it.
167	 *
168	 * A package importing itself by name is not a hole — that is a package reaching
169	 * its own subpath exports — and neither is a specifier that names no package at
170	 * all.
171	 */
172	export function undeclaredRuntimeDependencies(
173		packages: readonly InstalledPackage[],
174	): readonly UndeclaredRuntimeDependency[] {
175		const installed = new Set(packages.map((entry) => entry.name));
176		const holes: UndeclaredRuntimeDependency[] = [];
177		for (const importer of packages) {
178			const declared = new Set(importer.declared);
179			const byDependency = new Map<string, { specifiers: Set<string>; files: Set<string> }>();
180			for (const record of importer.imports) {
181				const dependency = packageNameOfSpecifier(record.specifier);
182				if (dependency === null || dependency === importer.name) continue;
183				if (declared.has(dependency)) continue;
184				const entry = byDependency.get(dependency) ?? { specifiers: new Set(), files: new Set() };
185				entry.specifiers.add(record.specifier);
186				entry.files.add(record.from);
187				byDependency.set(dependency, entry);
188			}
189			for (const dependency of [...byDependency.keys()].sort(compareStrings)) {
190				const entry = byDependency.get(dependency);
191				if (entry === undefined) continue;
192				holes.push(
193					Object.freeze({
194						importer: importer.name,
195						importerVersion: importer.version,
196						dependency,
197						specifiers: Object.freeze([...entry.specifiers].sort(compareStrings)),
198						files: Object.freeze([...entry.files].sort(compareStrings)),
199						satisfiedByClosure: installed.has(dependency),
200					}),
201				);
202			}
203		}
204		return Object.freeze(
205			holes.sort(
206				(left, right) =>
207					compareStrings(left.dependency, right.dependency) ||
208					compareStrings(left.importer, right.importer),
209			),
210		);
211	}
212	
213	export type RuntimeDependencyDeclaration = Readonly<{
214		field: 'dependencies';
215		name: string;
216		range: string;
217		reason: string;
218	}>;
219	
220	export type RuntimeDependencyDeclarations = Readonly<{
221		manifest: PackageManifest;
222		declarations: readonly RuntimeDependencyDeclaration[];
223		declaredDifferences: readonly string[];
224		unhandled: readonly string[];
225	}>;
226	
227	function applicationDeclares(manifest: PackageManifest, name: string): boolean {
228		for (const field of APPLICATION_DEPENDENCY_FIELDS) {
229			const value = manifest[field];
230			if (typeof value !== 'object' || value === null || Array.isArray(value)) continue;
231			if (name in (value as Record<string, unknown>)) return true;
232		}
233		return false;
234	}
235	
236	function describeHoles(holes: readonly UndeclaredRuntimeDependency[]): string {
237		return holes
238			.map(
239				(hole) =>
240					`${hole.importer}@${hole.importerVersion} imports it as ` +
241					`${hole.specifiers.join(', ')} from ${hole.files.join(', ')} but declares it in none of ` +
242					`${RUNTIME_DEPENDENCY_FIELDS.join(', ')}`,
243			)
244			.join('; ');
245	}
246	
247	/**
248	 * Close the holes in the application manifest.
249	 *
250	 * A hole the application already declares is left alone: the edge is already
251	 * stated, and restating it at the cell's range would be an upgrade decision
252	 * this capability is not making. A hole the cell has read no line for, or has
253	 * read and found no successor for, is reported and left open — the manifest
254	 * keeps saying nothing rather than saying something unverified.
255	 */
256	export function declareUndeclaredRuntimeDependencies(
257		manifest: PackageManifest,
258		holes: readonly UndeclaredRuntimeDependency[],
259		cell: AngularTargetCell,
260	): RuntimeDependencyDeclarations {
261		const byDependency = new Map<string, UndeclaredRuntimeDependency[]>();
262		for (const hole of holes) {
263			const entry = byDependency.get(hole.dependency) ?? [];
264			entry.push(hole);
265			byDependency.set(hole.dependency, entry);
266		}
267		const declarations: RuntimeDependencyDeclaration[] = [];
268		const declaredDifferences: string[] = [];
269		const unhandled: string[] = [];
270		const added: Record<string, string> = {};
271		for (const name of [...byDependency.keys()].sort(compareStrings)) {
272			const group = byDependency.get(name) ?? [];
273			if (applicationDeclares(manifest, name)) continue;
274			const disposition = ecosystemDispositionOf(name, cell);
275			if (disposition === null) {
276				unhandled.push(
277					`${name} is imported by the installed closure without being declared — ` +
278						`${describeHoles(group)} — but ${cell.id} has read no line for it, so the ` +
279						'manifest was left as it is rather than declaring an unverified version',
280				);
281				continue;
282			}
283			if (disposition.kind === 'no-successor') {
284				unhandled.push(
285					`${name} is imported by the installed closure without being declared — ` +
286						`${describeHoles(group)} — but ${cell.id} found no line of it to declare: ` +
287						disposition.fact,
288				);
289				continue;
290			}
291			added[name] = disposition.range;
292			const reason =
293				`declared to close an undeclared runtime dependency the installed closure supplied by ` +
294				`accident: ${describeHoles(group)}. Version read for ${cell.id}: ${disposition.fact}`;
295			declarations.push(
296				Object.freeze({ field: 'dependencies' as const, name, range: disposition.range, reason }),
297			);
298			declaredDifferences.push(
299				`dependencies.${name} was added: the migrated workspace declares a package the era ` +
300					`workspace never named. ${reason}`,
301			);
302		}
303		if (declarations.length === 0)
304			return Object.freeze({
305				manifest,
306				declarations: Object.freeze([]),
307				declaredDifferences: Object.freeze([]),
308				unhandled: Object.freeze(unhandled.sort(compareStrings)),
309			});
310		const current = manifest['dependencies'];
311		if (current !== undefined && (typeof current !== 'object' || current === null))
312			throw new Error('Undeclared runtime dependency declaration: "dependencies" is not an object');
313		const merged: Record<string, unknown> = {
314			...(current as Record<string, unknown> | undefined),
315			...added,
316		};
317		const sorted: Record<string, unknown> = {};
318		for (const key of Object.keys(merged).sort(compareStrings)) sorted[key] = merged[key];
319		return Object.freeze({
320			manifest: Object.freeze({ ...manifest, dependencies: Object.freeze(sorted) }),
321			declarations: Object.freeze(declarations),
322			declaredDifferences: Object.freeze(declaredDifferences.sort(compareStrings)),
323			unhandled: Object.freeze(unhandled.sort(compareStrings)),
324		});
325	}
