const TYPESCRIPT_MODULE = createRegExp(
	exactly('.').and(oneOrMore(charNotIn('.'))).and(exactly('.ts')).at.lineEnd(),
);

function describeSites(uses: readonly ApplicationPackageUse[]): string {
	return uses
